// generar_292_constancia_flechas_vet_y_cache.js
// CHIQUI Entre Señales — Estadísticas más útiles + fixes en la vista del vet
//
// 1) ESTADÍSTICAS DEL MES (Análisis · Actividad física)
//    "Promedio diario" daba el MISMO número que "Promedio por salida"
//    cuando se paseaba todos los días (uno divide por días con paseo,
//    el otro por días del mes; si paseas a diario, coinciden). Era
//    información redundante. Se reemplaza por CONSTANCIA: el % de días
//    del mes en que hubo paseo (ej. "84% de los días"), que sí aporta
//    algo nuevo y motivador.
//
// 2) VISTA DEL VETERINARIO — flechas de desplegar
//    Las secciones del vet usan <details> nativo con una flecha propia
//    que no entró en el cambio general (script 288). Ahora usan el
//    mismo triángulo relleno (▼) en café oscuro, que gira 180° al
//    abrir la sección (vía CSS sobre [open]).
//
// 3) VISTA DEL VETERINARIO — evoluciones no aparecían al instante  ★
//    Una evolución recién registrada (p. ej. la del grano de hoy) no
//    se veía en el vet hasta recargar. Causa: la página /vet es un
//    Server Component y Next.js la CACHEABA, sirviendo una versión
//    previa. Se agrega force-dynamic + revalidate 0 para que la vista
//    del vet NUNCA se cachee y siempre traiga lo más reciente. Así el
//    veterinario ve cada evolución apenas se registra, sin recargar.
//    (Las evoluciones anteriores sí se veían porque ya estaban en la
//    versión cacheada; la de hoy no, hasta forzar recarga.)
//
// No hay SQL.
//
// Uso:
//   node generar_292_constancia_flechas_vet_y_cache.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "app/analisis/page.tsx",
    base64: ""
  },
  {
    ruta: "app/vet/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 2 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
